@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5 p-5 bg-primary text-white rounded-3">
    <h1 class="display-4 fw-bold">University Course Catalog</h1>
    <p class="lead mb-4">Explore departments, browse courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn btn-light btn-lg me-2">Browse Courses</a>
    <a href="/enroll" class="btn btn-outline-light btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _featuredCourses)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <span class="badge bg-secondary mb-2">@dept?.Code</span>
                        <h5 class="card-title">@course.Code — @course.Title</h5>
                        <p class="card-text text-muted">@Truncate(course.Description, 120)</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-muted small">@course.Credits credits</span>
                            <span class="badge @(course.CurrentEnrollment >= course.MaxEnrollment ? "bg-danger" : "bg-success")">
                                @course.CurrentEnrollment / @course.MaxEnrollment seats
                            </span>
                        </div>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
        @foreach (var dept in _departments)
        {
            var courseCount = Catalog.GetCourses().Count(c => c.DepartmentId == dept.Id);
            <div class="col">
                <a href="/courses?department=@dept.Id" class="text-decoration-none">
                    <div class="card h-100 border-start border-primary border-4 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title text-dark">@dept.Name <span class="text-muted fw-normal">(@dept.Code)</span></h5>
                            <p class="card-text text-muted mb-1">@dept.Description</p>
                            <small class="text-primary">@courseCount course(s) available →</small>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> _featuredCourses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
}

