                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <input type="text" id="studentName" name="_model.StudentName" value="@_model.StudentName" class="form-control" required maxlength="100" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId" class="form-control" required pattern="[A-Za-z0-9]{6,12}" title="6–12 alphanumeric characters" />
                            <div class="form-text">Your university-issued student ID (6–12 alphanumeric characters).</div>
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                            <select id="courseId" name="_model.CourseId" class="form-select" required>
                                <option value="">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    if (course.Id == _model.CourseId)
                                    {
                                        <option value="@course.Id" selected>@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                    else
                                    {
                                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                }
                            </select>
                        </div>

                        <div class="mb-3">
                            <label for="comments" class="form-label">Comments (optional)</label>
                            <textarea id="comments" name="_model.Comments" class="form-control" rows="3" maxlength="500">@_model.Comments</textarea>
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                    </form>
                </div>
            </div>
        </div>

        <div class="col-lg-4 mt-4 mt-lg-0">
            <div class="card bg-light">
                <div class="card-body">
                    <h6 class="card-title">Enrollment Information</h6>
                    <ul class="small mb-0">
                        <li>Submitting this form sends a request to the registrar's office.</li>
                        <li>You will receive confirmation via your university email within 2 business days.</li>
                        <li>Enrollment is subject to prerequisite verification and seat availability.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private List<Course> _courses = [];
    private Course? _selectedCourse;
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (PreselectedCourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        _selectedCourse = Catalog.GetCourse(_model.CourseId);
        Catalog.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
}

